<?php
$suiteModule='reports';require __DIR__.'/../common.php';if (!isset($suiteWorkspace)) return;
$catalog=App\Enterprise\ReportService::CATALOG;$kind=is_string($_GET['report']??null)?$_GET['report']:'';
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$report=null;
if ($kind!==''&&isset($catalog[$kind])) {
    try {$report=(new App\Enterprise\ReportService($conn,$suiteUser))->report($kind,$_GET);}
    catch(InvalidArgumentException $error){echo '<div class="alert alert-warning">'.$suiteEscape($error->getMessage()).'</div>';}
}
?>
<div class="suite-heading mb-3"><h4 class="m-0">Report Center</h4><a class="btn btn-sm btn-outline-secondary" href="<?php echo base_url ?>admin/?page=finance/accounting&view=reports"><i class="fas fa-book mr-1"></i> Posted Financials</a></div>
<div class="suite-report-layout"><aside class="suite-report-nav"><label for="suite-report-search" class="sr-only">Find report</label><input class="form-control form-control-sm mb-3" id="suite-report-search" type="search" placeholder="Find report" autocomplete="off"><?php $groups=[];foreach($catalog as $key=>[$group,$name]) $groups[$group][$key]=$name;foreach($groups as $group=>$entries): ?><section class="suite-report-group"><h6><?php echo $group ?></h6><?php foreach($entries as $key=>$name): ?><a class="suite-report-link <?php echo $key===$kind?'active':'' ?>" href="<?php echo $suiteEscape($suiteUrl) ?>&report=<?php echo $key ?>"><?php echo $name ?></a><?php endforeach ?></section><?php endforeach ?></aside>
<section class="suite-report-output">
<?php if ($kind&&isset($catalog[$kind])): ?><h5><?php echo $catalog[$kind][1] ?></h5><form method="get" class="suite-report-filters suite-no-print"><input type="hidden" name="page" value="enterprise/reports"><input type="hidden" name="report" value="<?php echo $kind ?>"><div><label for="report-from">From</label><input class="form-control form-control-sm" id="report-from" name="from" type="date" required value="<?php echo $suiteEscape($from) ?>"></div><div><label for="report-to">To / As Of</label><input class="form-control form-control-sm" id="report-to" name="to" type="date" required value="<?php echo $suiteEscape($to) ?>"></div><div><label for="report-location">Location</label><select class="form-control form-control-sm" id="report-location" name="location_id"><option value="">All Locations</option><?php echo $suiteSelect($suiteLocations,'id','name',$_GET['location_id']??null) ?></select></div><div><label for="report-party">Party</label><select class="form-control form-control-sm suite-search-select" id="report-party" name="party_id"><option value="">All Parties</option><?php echo $suiteSelect($suiteOptions['parties'],'id','display_name',$_GET['party_id']??null) ?></select></div><div><label for="report-item">Item</label><select class="form-control form-control-sm suite-search-select" id="report-item" name="item_id"><option value="">All Items</option><?php echo $suiteSelect($suiteOptions['items'],'id','name',$_GET['item_id']??null) ?></select></div><div><label for="report-cash-account">Cash / Bank Account</label><select class="form-control form-control-sm" id="report-cash-account" name="account_id"><option value="">All Accounts</option><?php echo $suiteSelect($suiteOptions['accounts'],'id','name',$_GET['account_id']??null) ?></select></div>
<?php if (str_starts_with($kind,'comparative_')): foreach (['compare_from'=>'Compare From','compare_to'=>'Compare To'] as $key=>$name): ?><div><label for="report-<?php echo $key ?>"><?php echo $name ?></label><input class="form-control form-control-sm" id="report-<?php echo $key ?>" name="<?php echo $key ?>" type="date" value="<?php echo $suiteEscape($_GET[$key]??date('Y-m-d',strtotime(($key==='compare_from'?$from:$to).' -1 year'))) ?>"></div><?php endforeach;endif ?>
<?php if($kind==='break_even_payback'):foreach(['fixed_costs'=>'Fixed Costs Override','investment'=>'Investment','period_cash_flow'=>'Net Cash Flow per Period'] as $key=>$name): ?><div><label for="report-<?php echo $key ?>"><?php echo $name ?></label><input class="form-control form-control-sm" id="report-<?php echo $key ?>" name="<?php echo $key ?>" type="number" step="0.01" min="0" value="<?php echo $suiteEscape($_GET[$key]??'') ?>"></div><?php endforeach;endif ?>
<div class="suite-actions align-self-end"><button class="btn btn-primary btn-sm" type="submit"><i class="fas fa-filter mr-1"></i> Apply</button><?php if($report): ?><a class="btn btn-outline-secondary btn-sm" title="Download CSV" aria-label="Download CSV" href="<?php echo base_url ?>classes/Enterprise.php?<?php echo $suiteEscape(http_build_query(array_merge($_GET,['f'=>'report_export']))) ?>"><i class="fas fa-download"></i></a><button class="btn btn-outline-secondary btn-sm suite-print" title="Print report" aria-label="Print report" type="button"><i class="fas fa-print"></i></button><?php endif ?></div></form>
<?php if($report): ?><p class="suite-report-basis"><?php echo $suiteEscape($report['basis']) ?></p><div class="suite-report-caption"><?php echo $suiteEscape($report['from'].' to '.$report['to']) ?></div><?php $suiteTable($report['rows']); ?><span class="small text-muted"><?php echo count($report['rows']) ?> rows</span><?php endif ?>
<?php else: ?><h5>Reports</h5><div class="suite-report-directory"><?php foreach($groups as $group=>$entries): ?><section><h6><?php echo $group ?></h6><?php foreach($entries as $key=>$name): ?><a class="d-block py-1" href="<?php echo $suiteEscape($suiteUrl) ?>&report=<?php echo $key ?>"><?php echo $name ?></a><?php endforeach ?></section><?php endforeach ?></div><?php endif ?>
<?php if($report)require __DIR__.'/statement_share.php'; ?>
</section></div></div>
